"""Generate the client route policy and readable inventory from one source."""
import json,pathlib,sys
root=pathlib.Path(__file__).resolve().parents[1]
items=json.loads((root/'services/api/src/ad-placements.json').read_text())
lines=['// Generated by scripts/generate-ad-placements.py; edit the JSON inventory.','const bannerPlacements = <String, String>{']
lines += [f"  '{r['route']}': '{r['network']}'," for r in items if r['network']]
lines += ['};','']
outputs={root/'apps/mobile/lib/advertising/placements.dart':'\n'.join(lines)}
text=['# Распределение рекламных страниц','', '100 страниц: 50 — Яндекс, 50 — Google. Сеть закреплена за страницей; случайного выбора обычных баннеров нет.','', 'В Android Google означает AdMob, в браузере — AdSense. Если закреплённая сеть отключена или не дала баннер, место скрывается. Во время ввода с клавиатуры баннер скрыт. Диалоги камеры и полноэкранный ролик не содержат баннера.','', '| Страница | Маршрут | Сеть |','|---|---|---|']
text += [f"| {r['title']} | `{r['route']}` | {'Яндекс' if r['network']=='yandex' else 'Google'} |" for r in items if r['network']]
text += ['', '## Исключённые экраны','','| Маршрут | Причина |','|---|---|']
text += [f"| `{r['route']}` | {r['excluded_reason']} |" for r in items if not r['network']]
text += ['', '## Подписка за рекламу','', 'Android: перед каждым новым роликом случайный выбор 50/50 из доступных Яндекса и AdMob. При ошибке загрузки — одна попытка второй сети. Неполный просмотр, закрытие ролика и ошибка не дают награду. Просмотры разных сетей идут в один набор выбранной услуги. В браузере остаётся Rewarded Яндекса: предоставленный блок AdSense — баннер, а не Google Rewarded для браузера.','']
outputs[root/'docs/advertising/PAGES.md']='\n'.join(text)
for p,s in outputs.items():
 if '--check' in sys.argv:
  if not p.exists() or p.read_text()!=s:raise SystemExit(f'Out of date: {p}')
 else:p.write_text(s)
